def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    full_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    full_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in full_rows:
        out[r] = [2] * w
    for c in full_cols:
        for r in range(h):
            out[r][c] = 2
    return out
